from SSHLibrary import SSHClient
from SSHLibrary.abstractclient import SSHClientException
import logging
import telnetlib


class AaShellExecutor(object):

    def __init__(self, host, port, timeout=5):
        self.host = host
        self.port = port
        self.timeout = timeout
        self.tn = None
        self._log = logging.getLogger(__name__)

    def connect(self):
        """connect to telnet"""
        try:
            self.tn = telnetlib.Telnet(self.host, self.port, self.timeout)
        except IOError:
            self._log.warning("socket connect fail")
            raise
        if not self.tn.read_until("AaShell>", self.timeout):
            raise Exception("Please check whether AaShell already open.")

    def execute_command(self, command):
        """execute telnet command and return result"""
        self._log.debug(command)
        return self.tn.write(command + '\n')

    def read_until_regexp(self, regexp="AaShell>"):
        """read until regexp appear"""
        ret = self.tn.read_until(regexp, self.timeout)
        return "{}".format(ret)

    def close(self):
        """close telnet"""
        self.tn.close()


class Executor(object):

    def __init__(self, host_ip, ssh_username, ssh_password, ssh_port, ssh_prompt, timeout):
        self._ssh_client = SSHClient(host=host_ip, port=ssh_port, prompt=ssh_prompt, timeout=timeout)
        self._ssh_client.login(username=ssh_username, password=ssh_password, look_for_keys=True)
        self._log = logging.getLogger(__name__)
        self._is_localhost = host_ip in ('localhost', '127.0.0.1', 'None', None)

    def run(self, cmd):
        """
        Executes command and returns the output

        :param string cmd:      shell command to execute
        :return:                output of shell command
        :raises:                SSHClientException
        """
        self._log.debug('Executing command: {}'.format(cmd))
        out, err, rc = self._ssh_client.execute_command(cmd)
        self._log.debug(u'OUTPUT: {} \n\nERROR: {}\n\nRC:{}'.format(out, err, rc))
        if 0 != rc:
            raise SSHClientException(err)
        return out

    def execute_command(self, cmd):
        """
        Executes command and returns the output
        """
        self._log.debug('Executing command: {}'.format(cmd))
        out, err, rc = self._ssh_client.execute_command(cmd)
        if err:
            self._log.debug("err:{}".format(err))
        return out

    def execute_command_and_return_all_result(self, cmd):
        """
        Executes command and returns the output
        """
        self._log.debug('Executing command: {}'.format(cmd))
        out, err, rc = self._ssh_client.execute_command(cmd)
        if err:
            self._log.debug("err:{}".format(err))
        return out, err, rc

    def start(self, cmd):
        """
        Executes command and returns immediately

        :param string cmd:      shell command to execute
        """
        self._log.debug('Starting command: {}'.format(cmd))
        self._ssh_client.start_command(cmd)

    def write_to_shell(self, cmd):
        """
        Write command on the shell

        :param string cmd:      shell command to write in the shell
        """
        self._ssh_client.write(cmd)
        self._log.debug('Write to shell: {}'.format(cmd))

    def read_shell(self):
        """
        Read the shell contents

        :return string:    Current shell ouput
        """
        out = self._ssh_client.read_until_prompt()
        self._log.debug('Read shell: {}'.format(out))
        return out

    def read_until(self, expected):
        """
        """
        return self._ssh_client.read_until(expected)

    def read_until_regexp(self, regexp):
        """
        """
        return self._ssh_client.read_until_regexp(regexp)

    def get_file(self, source, destination):
        """get file from remote to local"""
        self._ssh_client.get_file(source=source, destination=destination)

    def put_file(self, source, destination):
        """put file from local to remote"""
        self._ssh_client.put_file(source=source, destination=destination)

    def get_logs(self, log_files, log_path):
        """
        Collect a directory and its contents from remote host to local

        :param list log_files:          source remote path
        :param string local_path:       destination local path
        """
        self._log.debug('Get logs: {} Destination: {}'.format(log_files, log_path))
        log_path = log_path.rstrip('/') + '/'
        if not self._is_localhost:
            for log_file in log_files:
                self._ssh_client.get_file(source=log_file, destination=log_path)

    def close_connection(self):
        """ Closes SSH connection """
        self._ssh_client.close()
        self._ssh_client = None
